<script setup>import {ref,computed} from 'vue';import {Head,useForm,usePage,router} from '@inertiajs/vue3';import {MapPin,Droplets} from 'lucide-vue-next';import Badge from '../Components/Badge.vue';import Errors from '../Components/Errors.vue';import {states,date} from '../lib/labels';const props=defineProps({points:Array,localities:Array,filters:Object});const user=usePage().props.auth?.user,canManage=['admin','gestionnaire'].includes(user?.role);const edit=ref(null),show=ref(false),q=ref(props.filters?.q||''),state=ref(props.filters?.state||'');const f=useForm({code:'',name:'',locality_id:'',equipment:'Pompe manuelle',community:'Communauté',landmark:'',state:'inconnu'});function open(p){edit.value=p?.id||null;f.defaults(p?{code:p.code,name:p.name,locality_id:p.locality_id,equipment:p.equipment,community:p.community,landmark:p.landmark,state:p.state}:{code:'',name:'',locality_id:'',equipment:'Pompe manuelle',community:'Communauté',landmark:'',state:'inconnu'});f.reset();show.value=true}function save(){f.post('/points-eau'+(edit.value?'/'+edit.value:''),{onSuccess:()=>show.value=false})}function next(p){return p.maintenances?.filter(m=>!m.completed_at).sort((a,b)=>a.scheduled_at.localeCompare(b.scheduled_at))[0]?.scheduled_at}function last(p){return p.maintenances?.filter(m=>m.completed_at).sort((a,b)=>b.completed_at.localeCompare(a.completed_at))[0]?.completed_at}</script><template><Head title="Points d’eau"/><div class="page-heading heading-row"><div><span class="eyebrow">LE RÉPERTOIRE DES ÉQUIPEMENTS</span><h1>Les points d’eau</h1><p>Un état déclaré, une localisation et un suivi pour chaque équipement.</p></div><button v-if="canManage" class="btn btn-primary" @click="open()">+ Ajouter un point d’eau</button></div><form class="filters" @submit.prevent="router.get('/points-eau',{q,state})"><input v-model="q" placeholder="Rechercher un point d’eau" aria-label="Nom du point d’eau"><select v-model="state" aria-label="État"><option value="">Tous les états</option><option v-for="(label,s) in states" :key="s" :value="s">{{label}}</option></select><button class="btn btn-soft">Filtrer</button></form><form v-if="show" class="card form-stack mt mb" @submit.prevent="save"><h3>{{edit?'Modifier':'Ajouter'}} un point d’eau</h3><Errors :errors="f.errors"/><div class="grid two"><label>Code<input v-model="f.code" required></label><label>Nom<input v-model="f.name" required></label><label>Localité<select v-model="f.locality_id" required><option value="" disabled>Choisir</option><option v-for="l in localities" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label>Équipement<input v-model="f.equipment" required></label><label>Public desservi<input v-model="f.community" required></label><label>État déclaré<select v-model="f.state"><option v-for="(label,s) in states" :key="s" :value="s">{{label}}</option></select></label></div><label>Repère<input v-model="f.landmark"></label><div class="button-row"><button class="btn btn-primary" :disabled="f.processing">Enregistrer</button><button class="btn btn-outline" type="button" @click="show=false">Fermer</button></div></form><div class="grid three"><article v-for="p in points" :key="p.id" class="card point-card"><div class="point-top"><span class="mini-icon blue"><Droplets/></span><span class="muted">{{p.code}}</span></div><h3>{{p.name}}</h3><p class="location"><MapPin :size="15"/>{{p.locality?.name}} · {{p.locality?.commune?.name}}</p><Badge :value="p.state"/><dl><div><dt>Équipement</dt><dd>{{p.equipment}}</dd></div><div><dt>Public desservi</dt><dd>{{p.community}}</dd></div><div><dt>Gestionnaire</dt><dd>{{p.manager?.name||'À désigner'}}</dd></div><div><dt>État actualisé le</dt><dd>{{date(p.state_updated_at)}}</dd></div><div><dt>Dernier entretien</dt><dd>{{date(last(p))}}</dd></div><div><dt>Prochain entretien</dt><dd>{{date(next(p))}}</dd></div></dl><p v-if="p.landmark" class="muted">{{p.landmark}}</p><button v-if="canManage" class="btn btn-soft small" @click="open(p)">Modifier la fiche</button></article></div><div v-if="!points.length" class="card empty">Aucun point d’eau trouvé.</div></template>
